class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        res = []
        n = len(grid)
        m = len(grid[0]) if n else 0
        count = 0
        for i in range(n):
            if i % 2 == 0:
                # left to right
                for j in range(m):
                    if count % 2 == 0:
                        res.append(grid[i][j])
                    count += 1
            else:
                # right to left
                for j in range(m - 1, -1, -1):
                    if count % 2 == 0:
                        res.append(grid[i][j])
                    count += 1
        return res
